 "content": "from collections import deque


def _components(grid, value=0):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != value or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.pop()
                comp.append((x, y))
                for a, b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == value and (a,b) not in seen:
                        seen.add((a,b))
                        q.append((a,b))
            result.append(comp)
    return result


def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid, 0)
    if not comps:
        return out
    # Paint the broadest open region 8 and the smallest distinct pocket 7.
    largest = max(comps, key=len)
    smallest = min(comps, key=len)
    for r, c in largest:
        out[r][c] = 8
    if smallest is not largest:
        for r, c in smallest:
            out[r][c] = 7
    return out
"
